begin;
select no_plan();
insert into public.profiles(id)values('19100810-0000-4000-8000-000000000001');
select * from public.operational_access_set('19100810-0000-4000-8000-000000000001','owner','grant','fixture','Sync audit owner','sync-audit-owner',null);
alter table private.admin_effects add constraint sync_test_recorder_down check(action<>'sync_payments');
select throws_ok($$select public.native_admin_payment_sync_budget('19100810-0000-4000-8000-000000000001','sandbox','19100810-0000-4000-8000-000000000009')$$,'23514',null,'unavailable journal aborts quota reservation');
select is((select count(*)::integer from private.admin_payment_sync_budget),0,'audit failure consumes no quota');
alter table private.admin_effects drop constraint sync_test_recorder_down;
select ok(public.native_admin_payment_sync_budget('19100810-0000-4000-8000-000000000001','sandbox','19100810-0000-4000-8000-000000000010'),'winning quota commits its intention');
select is((select count(*)::integer from private.admin_effects where effect_id='19100810-0000-4000-8000-000000000010' and actor='19100810-0000-4000-8000-000000000001' and action='sync_payments' and effect='polar_payment_sync' and outcome='started' and occurred_at is not null),1,'journal contains actor/action/date/start');
select ok(not public.native_admin_payment_sync_budget('19100810-0000-4000-8000-000000000001','sandbox','19100810-0000-4000-8000-000000000011'),'loser spends no quota');
select is((select count(*)::integer from private.admin_effects where effect_id='19100810-0000-4000-8000-000000000011'),0,'losing quota creates no effect');
select ok((select target_account is null and not erase_on_close and provider_status is null and target_hash=encode(sha256(convert_to('sync_payments:sandbox','UTF8')),'hex') from private.admin_effects where effect_id='19100810-0000-4000-8000-000000000010'),'10b: technical target has no account/email/URL/provider ID');
select ok(public.native_admin_record_payment_sync('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000010','unknown'),'failed import closes uncertain');
select is((select latest_outcome from private.admin_pending_effects where effect_id='19100810-0000-4000-8000-000000000010'),'unknown','uncertain import appears in the existing pending view');
select ok(public.native_admin_reconcile_effect('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000010'),'owner reconciles the existing journal');
select ok(not exists(select 1 from private.admin_pending_effects where effect_id='19100810-0000-4000-8000-000000000010'),'reconcile removes pending');
update private.admin_payment_sync_budget set window_start=clock_timestamp()-interval '61 seconds';
select ok(public.native_admin_payment_sync_budget('19100810-0000-4000-8000-000000000001','sandbox','19100810-0000-4000-8000-000000000012'),'next import has a distinct intention');
update public.operational_access_assignments set granted_at=now()-interval '2 days',expires_at=now()-interval '1 day' where user_id='19100810-0000-4000-8000-000000000001';
select ok(public.native_admin_record_payment_sync('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000012','succeeded'),'matched result closes after owner expiry');
select ok(public.native_admin_record_payment_sync('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000012','succeeded'),'same result retry is idempotent');
select is((select count(*)::integer from private.admin_effects where effect_id='19100810-0000-4000-8000-000000000012'),2,'retry does not duplicate outcome');
select throws_ok($$select public.native_admin_record_payment_sync('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000099','succeeded')$$,'22023','native_admin_invalid','result requires its committed intention');
select throws_ok($$select public.native_admin_record_payment_sync('19100810-0000-4000-8000-000000000001','19100810-0000-4000-8000-000000000012','started')$$,'22023','native_admin_invalid','result RPC cannot fabricate an intention');
select ok(not has_function_privilege('anon','public.native_admin_record_payment_sync(uuid,uuid,text)','EXECUTE') and not has_function_privilege('authenticated','public.native_admin_record_payment_sync(uuid,uuid,text)','EXECUTE'),'only service can record results');
select * from finish();
rollback;
